struct UncommittedLayout<'a> {
    task: &'a ResolvedTask,
    armed: bool,
}

#[derive(Debug)]
pub(crate) enum RegistryError {
    TaskNotFound(String),
    TaskLimit(String),
    StartupDeadline(String),
    Operation(String),
}

impl RegistryError {
    pub(crate) fn is_missing_task(&self) -> bool {
        matches!(self, Self::TaskNotFound(_))
    }
}

impl std::fmt::Display for RegistryError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::TaskNotFound(id) => write!(f, "background task not found: {id}"),
            Self::TaskLimit(message)
            | Self::StartupDeadline(message)
            | Self::Operation(message) => f.write_str(message),
        }
    }
}

impl From<String> for RegistryError {
    fn from(message: String) -> Self {
        Self::Operation(message)
    }
}

impl From<&str> for RegistryError {
    fn from(message: &str) -> Self {
        Self::Operation(message.into())
    }
}

impl<'a> UncommittedLayout<'a> {
    fn new(task: &'a ResolvedTask) -> Self {
        Self { task, armed: true }
    }

    fn disarm(mut self) {
        // Once a receipt/record commits, status must retain even a failed
        // launch. Later failure handling owns that record, not this guard.
        self.armed = false;
    }
}

impl Drop for UncommittedLayout<'_> {
    fn drop(&mut self) {
        if self.armed {
            let _ = delete_resolved_task(self.task);
        }
    }
}
/// Default timeout for background bash tasks: 30 minutes.
/// Agents can override per-call via the `timeout` parameter (in ms); see
/// [`super::HardKill`].
pub(crate) const DEFAULT_BG_TIMEOUT: Duration = Duration::from_secs(30 * 60);

thread_local! {
    static LEDGER_SPAWN: std::cell::RefCell<Option<crate::db::call_ledger::Key>> = const { std::cell::RefCell::new(None) };
    static SCOPE_SPAWN: std::cell::RefCell<Option<subc_protocol::scope::ScopeStamp>> = const { std::cell::RefCell::new(None) };
}

/// Carry the shell task's daemon-authenticated scope identity separately
/// from tool arguments, so the caller cannot invent or change its owner.
pub(crate) fn with_scope_spawn<T>(
    scope: Option<subc_protocol::scope::ScopeStamp>,
    run: impl FnOnce() -> T,
) -> T {
    struct Restore(Option<subc_protocol::scope::ScopeStamp>);
    impl Drop for Restore {
        fn drop(&mut self) {
            SCOPE_SPAWN.with(|slot| *slot.borrow_mut() = self.0.take());
        }
    }
    let _restore = Restore(SCOPE_SPAWN.with(|slot| slot.replace(scope)));
    run()
}

pub(crate) fn scope_for_spawn() -> Option<subc_protocol::scope::ScopeStamp> {
    SCOPE_SPAWN.with(|slot| slot.borrow().clone())
}

/// The registry's first task write runs synchronously during dispatch. Carry
/// its durable admission identity without putting host data in tool arguments.
pub(crate) fn with_ledger_spawn<T>(
    key: Option<crate::db::call_ledger::Key>,
    run: impl FnOnce() -> T,
) -> T {
    struct Restore(Option<crate::db::call_ledger::Key>);
    impl Drop for Restore {
        fn drop(&mut self) {
            LEDGER_SPAWN.with(|slot| *slot.borrow_mut() = self.0.take());
        }
    }
    let _restore = Restore(LEDGER_SPAWN.with(|slot| slot.replace(key)));
    run()
}

/// The call-ledger key a task created on this thread now would be linked to.
#[cfg(test)]
pub(crate) fn ledger_spawn_for_test() -> Option<crate::db::call_ledger::Key> {
    LEDGER_SPAWN.with(|slot| slot.borrow().clone())
}
/// How far past the last written hard-kill limit a renewal must reach before
/// it is written to the task's record (see `BgTaskRegistry::renew_hard_kill`).
pub(crate) const RENEWAL_PERSIST_STEP_MS: u64 = 60_000;
const PERSISTED_GC_GRACE: Duration = Duration::from_secs(24 * 60 * 60);
const QUARANTINE_GC_GRACE: Duration = Duration::from_secs(30 * 24 * 60 * 60);
/// Bounded retries keep transient file locks from losing task history forever.
const FINISHED_DELETE_MAX_ATTEMPTS: usize = 5;

const TOKENIZE_CAP_BYTES_PER_STREAM: usize = 128 * 1024;
pub const ROOT_RECLAIMED_REASON: &str = "root_reclaimed";
/// Status reason of a task killed because its caller withdrew the call.
pub const WITHDRAWN_REASON: &str = "withdrawn";
pub const SCOPE_REVOKED_REASON: &str = "scope_revoked";
pub(crate) const OWNER_PAUSED_REASON: &str = "paused_by_owner";
/// Status reason of a task a codemode program started, killed because the
/// daemon confirmed the program's run scope ended.
pub const RUN_ENDED_REASON: &str = "run_ended";

/// How an owner-directed stop is labelled to the agent: a run or scope end,
/// or a cancellation that leaves the scope usable.
/// `None` for any other status reason.
pub(crate) fn scope_end_label(reason: Option<&str>) -> Option<&'static str> {
    match reason {
        Some(SCOPE_REVOKED_REASON | "scope revoked") => Some("scope revoked"),
        Some(RUN_ENDED_REASON) => Some("run ended"),
        Some(OWNER_PAUSED_REASON) => Some("cancelled by owner"),
        _ => None,
    }
}
