/// How long a reader that must answer with a settled status (`bash_status`,
/// a second kill) waits for a kill already in flight on the same task: the
/// SIGTERM grace period plus a margin for the SIGKILL, the reap and the
/// terminal write. A kill still in flight after that (a signal stuck in the
/// kernel) is reported as in flight rather than waited out.
const KILL_IN_FLIGHT_WAIT: Duration =
    Duration::from_secs(super::process::TERMINATE_GRACE.as_secs() + 2);

fn log_bash_spawn(task_id: &str, pid: u32, session: &str, root: &Path, command: &str) {
    // Mask before shortening: a credential cut by the length limit would no
    // longer match its pattern.
    let command: String = crate::log_redact::redact_command(command)
        .chars()
        .take(200)
        .map(|character| match character {
            '\n' | '\r' => ' ',
            other => other,
        })
        .collect();
    let line = format!(
        "bash spawned task={task_id} pid={pid} session={session} root={} cmd={command}",
        root.display()
    );
    crate::slog_info!("{line}");
}

/// Bound the ConPTY close/output drain after the child has exited. A stuck
/// conhost or reader must not keep the task running forever or claim that all
/// output was captured.
#[cfg(any(windows, test))]
const PTY_OUTPUT_DRAIN_TIMEOUT: Duration = Duration::from_secs(5);

#[cfg(any(windows, test))]
enum PtyOutputDrainPoll {
    Pending,
    Ready,
    Incomplete(&'static str),
}

/// What a kill does after it releases the task's state lock. See
/// [`BgTaskRegistry::kill_with_status_reason`].
enum KillSignalPlan {
    /// Nothing to signal; the locked step already settled the task.
    Nothing,
    /// Another kill is signaling this task; wait for its outcome.
    AwaitOtherKill,
    /// The task is already terminal but members of its process group were
    /// still alive when it ended.
    TerminalSurvivors { pgid: i32, live_count: usize },
    /// Signal a piped task's process group and reap its direct child.
    Piped {
        pgid: Option<i32>,
        child_pid: Option<u32>,
        child: Option<Child>,
    },
    /// The task had already exited; close its retired PTY runtime, if any.
    RetirePty(Option<PtyRuntime>),
    /// A Windows PTY has an exit marker, but its reader must drain before a
    /// natural completion can be published, even when observed by a kill.
    #[cfg(any(windows, test))]
    DrainPty,
    /// Signal a PTY task's process group, then close its pseudoterminal so
    /// the PTY reader reaches end-of-file.
    Pty {
        pid: Option<u32>,
        master: Option<Box<dyn portable_pty::MasterPty + Send>>,
    },
}

/// Signal a piped task: SIGTERM to its process group, a grace period that
/// ends early once the direct child exits, then SIGKILL (Unix); `taskkill`
/// on the process tree (Windows).
fn terminate_piped_task(
    task_id: &str,
    pgid: Option<i32>,
    child_pid: Option<u32>,
    #[allow(unused_mut)] mut child: Option<&mut Child>,
) {
    #[cfg(all(test, unix))]
    if TERM_ONLY_KILL_TASKS
        .get()
        .is_some_and(|tasks| tasks.lock().unwrap().remove(task_id))
    {
        if let Some(pgid) = pgid {
            unsafe {
                libc::killpg(pgid, libc::SIGTERM);
            }
        }
        return;
    }
    let _ = task_id;
    #[cfg(unix)]
    {
        let _ = child_pid;
        if let Some(pgid) = pgid {
            super::process::terminate_pgid_with(pgid, || {
                child
                    .as_deref_mut()
                    .is_some_and(|child| matches!(child.try_wait(), Ok(Some(_))))
            });
        }
    }
    #[cfg(windows)]
    {
        let _ = pgid;
        if let Some(child) = child {
            super::process::terminate_process(child);
        } else if let Some(pid) = child_pid {
            terminate_pid(pid);
        }
    }
}

// Sending a group signal and reaping its leader do not mean descendants have
// exited yet. Settle the signalled group before sampling the kill completion,
// but keep reporting real survivors when this bounded grace expires.
#[cfg(unix)]
const KILL_GROUP_SETTLEMENT_GRACE: Duration = Duration::from_secs(2);

#[cfg(all(test, unix))]
static TERM_ONLY_KILL_TASKS: std::sync::OnceLock<Mutex<std::collections::HashSet<String>>> =
    std::sync::OnceLock::new();
#[cfg(all(test, unix))]
static KILL_SETTLEMENT_NOTICES: std::sync::OnceLock<
    Mutex<HashMap<String, crossbeam_channel::Sender<()>>>,
> = std::sync::OnceLock::new();
#[cfg(all(test, unix))]
thread_local! {
    static KILL_SETTLEMENT_TEST_NOW: std::cell::Cell<Option<Instant>> = const { std::cell::Cell::new(None) };
}

#[cfg(unix)]
fn kill_settlement_now() -> Instant {
    #[cfg(test)]
    if let Some(now) = KILL_SETTLEMENT_TEST_NOW.with(std::cell::Cell::get) {
        return now;
    }
    Instant::now()
}

#[cfg(unix)]
fn settle_killed_process_group(task_id: &str, pgid: Option<i32>) {
    let Some(pgid) = pgid else {
        return;
    };
    let started = kill_settlement_now();
    loop {
        let exists = unsafe { libc::killpg(pgid, 0) } == 0;
        if !exists && std::io::Error::last_os_error().raw_os_error() == Some(libc::ESRCH) {
            return;
        }
        // Zombies cannot run or retain output pipes. An unreaped orphan may
        // still make killpg(0) succeed, but is not a live descendant to report.
        if live_process_group_members(pgid)
            .is_some_and(|(members, omitted)| members.is_empty() && omitted == 0)
        {
            return;
        }
        #[cfg(test)]
        if let Some(notice) = KILL_SETTLEMENT_NOTICES
            .get()
            .and_then(|notices| notices.lock().unwrap().remove(task_id))
        {
            let _ = notice.send(());
        }
        let _ = task_id;
        if kill_settlement_now().saturating_duration_since(started) >= KILL_GROUP_SETTLEMENT_GRACE {
            return;
        }
        std::thread::sleep(Duration::from_millis(10));
    }
}

#[cfg(not(unix))]
fn settle_killed_process_group(_task_id: &str, _pgid: Option<i32>) {}

/// Close a PTY's pseudoterminal so its reader reaches end-of-file and
/// the task can finalize. On Windows, ConPTY's reader sees end-of-file only
/// once the pseudoconsole is closed, and closing it can wait for conhost to
/// flush; it runs on its own thread so no caller (or lock) waits on that.
fn close_pty_master(master: Option<Box<dyn portable_pty::MasterPty + Send>>) {
    let Some(master) = master else {
        return;
    };
    #[cfg(windows)]
    close_pty_master_off_thread(Some(master));
    #[cfg(not(windows))]
    drop(master);
}

#[cfg(any(windows, test))]
fn close_pty_master_off_thread(master: Option<Box<dyn portable_pty::MasterPty + Send>>) {
    let Some(master) = master else {
        return;
    };
    let spawned = std::thread::Builder::new()
        .name("aft-pty-close".to_owned())
        .spawn(move || drop(master));
    if let Err(error) = spawned {
        crate::slog_warn!("[pty-close] could not close the pseudoconsole off-thread: {error}");
    }
}

fn terminate_pty_group(pid: u32) {
    #[cfg(unix)]
    terminate_pgid(pid as i32, None);
    #[cfg(windows)]
    terminate_pid(pid);
}

/// Test gates that park a piped-task kill after it has published `Killing`
/// and released the state lock, before it signals, so a test can act while
/// the kill is in flight. Keyed by task id so parallel tests do not collide.
#[cfg(test)]
struct KillSignalGate {
    reached: crossbeam_channel::Sender<()>,
    release: crossbeam_channel::Receiver<()>,
}

#[cfg(test)]
static KILL_SIGNAL_GATES: std::sync::OnceLock<Mutex<HashMap<String, KillSignalGate>>> =
    std::sync::OnceLock::new();

// Park a terminal publisher after it releases the state lock but before it
// queues the completion. The channel pair is the same as the kill-signal gate.
#[cfg(test)]
static TERMINAL_PUBLICATION_GATES: std::sync::OnceLock<Mutex<HashMap<String, KillSignalGate>>> =
    std::sync::OnceLock::new();

#[cfg(test)]
static REHYDRATED_REGISTRATION_GATES: std::sync::OnceLock<Mutex<HashMap<String, KillSignalGate>>> =
    std::sync::OnceLock::new();

#[cfg(test)]
fn wait_on_rehydrated_registration_gate_for_test(task_id: &str) {
    let gate = REHYDRATED_REGISTRATION_GATES
        .get()
        .and_then(|gates| gates.lock().unwrap().remove(task_id));
    if let Some(gate) = gate {
        let _ = gate.reached.send(());
        let _ = gate.release.recv_timeout(Duration::from_secs(30));
    }
}

#[cfg(test)]
#[cfg_attr(not(unix), allow(dead_code))]
pub(crate) fn install_kill_signal_gate_for_test(
    task_id: &str,
) -> (
    crossbeam_channel::Receiver<()>,
    crossbeam_channel::Sender<()>,
) {
    let (reached_tx, reached_rx) = crossbeam_channel::bounded(1);
    let (release_tx, release_rx) = crossbeam_channel::bounded(1);
    KILL_SIGNAL_GATES
        .get_or_init(|| Mutex::new(HashMap::new()))
        .lock()
        .unwrap()
        .insert(
            task_id.to_string(),
            KillSignalGate {
                reached: reached_tx,
                release: release_rx,
            },
        );
    (reached_rx, release_tx)
}

#[cfg(test)]
fn wait_on_kill_signal_gate_for_test(task_id: &str) {
    let gate = KILL_SIGNAL_GATES
        .get()
        .and_then(|gates| gates.lock().unwrap().remove(task_id));
    if let Some(gate) = gate {
        let _ = gate.reached.send(());
        let _ = gate.release.recv_timeout(Duration::from_secs(30));
    }
}

#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
struct FinishedDeletePark {
    reached: crossbeam_channel::Sender<()>,
    release: crossbeam_channel::Receiver<()>,
}

#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
static FINISHED_DELETE_PARKS: std::sync::OnceLock<Mutex<HashMap<String, FinishedDeletePark>>> =
    std::sync::OnceLock::new();

/// A task-specific deletion fence for integration tests. Dropping the fence
/// releases cleanup even if an assertion fails before the explicit release.
#[doc(hidden)]
#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
pub struct FinishedDeleteGateForTest {
    task_id: String,
    reached: crossbeam_channel::Receiver<()>,
    release: Option<crossbeam_channel::Sender<()>>,
}

#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
impl FinishedDeleteGateForTest {
    pub fn wait_until_parked(
        &self,
        timeout: Duration,
    ) -> Result<(), crossbeam_channel::RecvTimeoutError> {
        self.reached.recv_timeout(timeout)
    }

    pub fn release(&mut self) {
        if let Some(release) = self.release.take() {
            let _ = release.send(());
        }
    }
}

#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
impl Drop for FinishedDeleteGateForTest {
    fn drop(&mut self) {
        self.release();
        if let Some(parks) = FINISHED_DELETE_PARKS.get() {
            parks.lock().unwrap().remove(&self.task_id);
        }
    }
}

#[cfg(any(debug_assertions, feature = "test-timing-hooks"))]
fn wait_on_finished_delete_gate_for_test(task_id: &str) {
    let park = FINISHED_DELETE_PARKS
        .get()
        .and_then(|parks| parks.lock().unwrap().remove(task_id));
    if let Some(park) = park {
        let _ = park.reached.send(());
        // Only the test's release channel can end this pause. An elapsed-time
        // auto-release would invalidate a concurrent status-operation proof.
        let _ = park.release.recv();
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct BgCompletion {
    #[serde(
        rename = "_bash_changed_files",
        skip_serializing_if = "Option::is_none"
    )]
    pub changed_files: Option<crate::bash_changed_files::Report>,
    pub task_id: String,
    /// Intentionally omitted from serialized completion payloads: push frames
    /// carry `session_id` at the BashCompletedFrame envelope level for routing.
    #[serde(skip_serializing)]
    pub session_id: String,
    pub status: BgTaskStatus,
    pub exit_code: Option<i64>,
    pub command: String,
    /// Small head+tail preview of the cached terminal render at completion time,
    /// cached so push-frame consumers and `bash_drain_completions` callers see
    /// the same preview without racing against later output rotation. Empty
    /// when not captured (e.g., persisted task seen on startup before buffer
    /// reattachment).
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub output_preview: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bash_output_list_envelope: Option<ListEnvelope>,
    /// True when the captured tail is shorter than the actual output (because
    /// rotation occurred or the output exceeds the preview cap). Plugins use
    /// this to render a `…` prefix and signal that `bash_status` would return
    /// more.
    #[serde(default, skip_serializing_if = "is_false")]
    pub output_truncated: bool,
    /// Token count for the capped raw stdout+stderr payload before compression.
    /// Omitted when capture or tokenization fails, or the exact count will not fit.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub original_tokens: Option<u32>,
    /// Token count for the compressed output generated from the same capped
    /// raw payload. Omitted when either token count is unavailable.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub compressed_tokens: Option<u32>,
    /// True when exact token counts are unavailable, including capture/read
    /// failures, pre-tokenizer errors and counts that cannot be represented.
    #[serde(default, skip_serializing_if = "is_false")]
    pub tokens_skipped: bool,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub status_reason: Option<String>,
    /// Output capture was incomplete, without changing the command's outcome.
    #[serde(default, skip_serializing_if = "is_false")]
    pub output_incomplete: bool,
    pub live_descendants: Option<Vec<LiveDescendant>>,
    #[serde(default, skip_serializing_if = "is_zero_usize")]
    pub live_descendants_omitted: usize,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub live_descendants_summary: Option<String>,
}

fn is_zero_usize(value: &usize) -> bool {
    *value == 0
}

fn is_false(v: &bool) -> bool {
    !*v
}

/// Where a task's hard kill comes from, so replies can tell AFT's default
/// background limit apart from a `timeout` the caller passed.
#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum HardKillSource {
    /// AFT's default background limit ([`DEFAULT_BG_TIMEOUT`]), possibly
    /// extended by a delegated worker's waits.
    Default,
    /// The caller's explicit `timeout`.
    Timeout,
}

/// A task's own kill deadline: it is killed once it has run `limit_ms`.
/// Distinct from how long any wait on it lasts.
#[derive(Debug, Clone, Copy, Serialize, PartialEq, Eq)]
pub struct HardKillDeadline {
    pub limit_ms: u64,
    pub source: HardKillSource,
}

impl HardKillDeadline {
    /// The deadline a task record carries. `renewable` is the record's
    /// `default_hard_kill`; for a record written before AFT stored it, a
    /// limit equal to the default is taken to be the default.
    fn from_metadata(timeout_ms: Option<u64>, renewable: bool) -> Option<Self> {
        let limit_ms = timeout_ms?;
        let source = if renewable || limit_ms == DEFAULT_BG_TIMEOUT.as_millis() as u64 {
            HardKillSource::Default
        } else {
            HardKillSource::Timeout
        };
        Some(Self { limit_ms, source })
    }
}

