    /// Attach fresh scratch holding one file to a finished task, as a spawn
    /// records it, and return the scratch directory and the task's exit time.
    #[cfg(unix)]
    fn attach_scratch(task: &BgTask) -> (PathBuf, u64) {
        let scratch = crate::sandbox_spawn::create_task_temp_dir(&task.paths.io_dir).unwrap();
        fs::write(scratch.join("note.txt"), "kept").unwrap();
        let mut state = task.lock_state().unwrap();
        state.metadata.sandbox_temp_dir = Some(scratch.clone());
        write_task(&task.paths.json, &state.metadata).unwrap();
        (scratch, state.metadata.finished_at.unwrap())
    }

    /// Run real-clock cleanup until the scratch is gone, as the watchdog does
    /// after a sweep or a scope end has released it.
    #[cfg(unix)]
    fn wait_for_released_scratch(registry: &BgTaskRegistry, task: &BgTask) {
        let deadline = Instant::now() + Duration::from_secs(10);
        while !registry.cleanup_terminal_task_temp(task).unwrap() {
            assert!(
                Instant::now() < deadline,
                "released scratch was not deleted"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
    }

    #[cfg(unix)]
    fn retention_ms() -> u64 {
        SCRATCH_RETENTION.as_millis() as u64
    }

    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_keeps_scratch_until_its_delete_time() {
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let (_, task) = insert_terminal_piped_task(&registry, &dir, "true", "", "", false);
        let (scratch, finished_at) = attach_scratch(&task);
        let delete_at = finished_at + retention_ms();

        // Right after exit the scratch stays, still recorded on the task, and
        // the delete time is in the task record for a later restart.
        assert!(registry
            .cleanup_terminal_task_temp_at(&task, finished_at + 1)
            .unwrap());
        assert_eq!(
            fs::read_to_string(scratch.join("note.txt")).unwrap(),
            "kept"
        );
        assert_eq!(
            task.lock_state().unwrap().metadata.sandbox_temp_dir,
            Some(scratch.clone())
        );
        assert_eq!(
            read_task(&task.paths.json).unwrap().sandbox_temp_delete_at,
            Some(delete_at)
        );
        assert!(!registry
            .inner
            .watchdog_tasks
            .lock()
            .unwrap()
            .contains_key(&task.task_id));
        let health = registry.try_retained_scratch_health().unwrap();
        assert_eq!(
            (health.count, health.bytes, health.bytes_state),
            (1, None, "unmeasured")
        );

        // A sweep before the delete time keeps it and measures it.
        registry.sweep_retained_scratch_at(delete_at - 1);
        assert!(scratch.join("note.txt").is_file());
        assert!(registry
            .cleanup_terminal_task_temp_at(&task, delete_at - 1)
            .unwrap());
        assert!(scratch.join("note.txt").is_file());
        let health = registry.try_retained_scratch_health().unwrap();
        assert_eq!(
            (
                health.count,
                health.bytes,
                health.bytes_state,
                health.unmeasured
            ),
            (1, Some(4), "measured", 0)
        );

        // Once the time passes the sweep hands it back to the watchdog, which
        // deletes it; reads then take the removed-scratch not-found path.
        registry.sweep_retained_scratch_at(delete_at);
        assert!(registry
            .inner
            .watchdog_tasks
            .lock()
            .unwrap()
            .contains_key(&task.task_id));
        wait_for_released_scratch(&registry, &task);
        assert!(!scratch.exists());
        assert!(read_task(&task.paths.json)
            .unwrap()
            .sandbox_temp_dir
            .is_none());
        assert_eq!(task.lock_state().unwrap().removed_temp_dir, Some(scratch));
        assert_eq!(registry.try_retained_scratch_health().unwrap().count, 0);
    }

    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_release_preserves_one_cleanup_backoff_step() {
        for scope_end in [false, true] {
            let registry = BgTaskRegistry::default();
            let dir = tempfile::tempdir().unwrap();
            let (_, task) = insert_terminal_piped_task(&registry, &dir, "true", "", "", false);
            let scope = subc_protocol::scope::ScopeStamp::new(
                subc_protocol::Principal::Reserved {
                    module_id: "owner".into(),
                },
                "retained",
                1,
                subc_protocol::scope::ScopeKind::Head,
            )
            .with_owner_authorized(true);
            task.lock_state().unwrap().metadata.scope = Some(scope.clone());
            let (scratch, finished_at) = attach_scratch(&task);
            assert!(registry
                .cleanup_terminal_task_temp_at(&task, finished_at + 1)
                .unwrap());

            // Seed the longest retry step to prove retention release does not
            // wait for, or restart, the deletion worker's failure backoff.
            let retry_started = Instant::now();
            for _ in 0..10 {
                task.lock_state()
                    .unwrap()
                    .temp_cleanup_retry
                    .failed(retry_started);
            }
            if scope_end {
                registry.kill_scope(&scope);
            } else {
                registry.sweep_retained_scratch_at(finished_at + retention_ms());
            }
            assert_eq!(registry.try_retained_scratch_health().unwrap().count, 0);
            assert!(registry
                .inner
                .watchdog_tasks
                .lock()
                .unwrap()
                .contains_key(&task.task_id));
            for _ in 0..64 {
                assert!(!registry.cleanup_terminal_task_temp(&task).unwrap());
                let state = task.lock_state().unwrap();
                assert!(state.scratch_released);
                assert!(state.temp_cleanup.is_none());
                assert!(!state
                    .temp_cleanup_retry
                    .ready(retry_started + Duration::from_secs(299)));
                assert!(state
                    .temp_cleanup_retry
                    .ready(retry_started + Duration::from_secs(300)));
            }

            // Move the failure clock into the past instead of sleeping through
            // five minutes; the next observer must schedule the real deletion.
            task.lock_state()
                .unwrap()
                .temp_cleanup_retry
                .failed(Instant::now() - Duration::from_secs(301));
            wait_for_released_scratch(&registry, &task);
            assert!(!scratch.exists());
        }
    }

    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_restart_honors_the_recorded_delete_time() {
        let now = unix_millis();
        // (recorded delete time, exit time, kept after replay)
        for (delete_at, finished_at, kept) in [
            (Some(now + 60_000), now, true),
            (Some(1), now, false),
            // Records written before scratch was kept count from their exit.
            (None, now, true),
            (None, now - retention_ms() - 1, false),
        ] {
            let registry = BgTaskRegistry::default();
            let dir = tempfile::tempdir().unwrap();
            let paths = task_paths(dir.path(), "session", &random_slug()).unwrap();
            fs::create_dir_all(&paths.io_dir).unwrap();
            let scratch = crate::sandbox_spawn::create_task_temp_dir(&paths.io_dir).unwrap();
            let mut metadata = PersistedTask::starting(
                paths.task_id.clone(),
                "session".into(),
                "true".into(),
                dir.path().into(),
                None,
                None,
                false,
                false,
            );
            metadata.mark_terminal(BgTaskStatus::Completed, Some(0), None);
            metadata.finished_at = Some(finished_at);
            metadata.sandbox_temp_dir = Some(scratch.clone());
            metadata.sandbox_temp_delete_at = delete_at;
            write_task(&paths.json, &metadata).unwrap();
            registry
                .rehydrate_resolved_task(metadata, paths.clone(), "session")
                .unwrap();
            let task = registry.task(&paths.task_id).unwrap();
            let case = format!("delete_at={delete_at:?} finished_at={finished_at}");
            if kept {
                assert!(scratch.is_dir(), "{case}: replay deleted kept scratch");
                assert_eq!(
                    read_task(&paths.json).unwrap().sandbox_temp_dir,
                    Some(scratch.clone()),
                    "{case}"
                );
                assert_eq!(registry.try_retained_scratch_health().unwrap().count, 1);
                wait_for_task_temp_cleanup(&registry, &task);
            } else {
                assert!(
                    registry
                        .inner
                        .watchdog_tasks
                        .lock()
                        .unwrap()
                        .contains_key(&paths.task_id),
                    "{case}: due scratch was not handed to the watchdog"
                );
                wait_for_released_scratch(&registry, &task);
                assert_eq!(registry.try_retained_scratch_health().unwrap().count, 0);
            }
            assert!(!scratch.exists(), "{case}");
        }
    }

    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_scope_end_deletes_early() {
        let stamp = |scope_ref: &str| {
            subc_protocol::scope::ScopeStamp::new(
                subc_protocol::Principal::Reserved {
                    module_id: "owner".into(),
                },
                scope_ref,
                1,
                subc_protocol::scope::ScopeKind::Head,
            )
            .with_owner_authorized(true)
        };
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let mut kept = Vec::new();
        for scope_ref in ["ended", "other"] {
            let (_, task) = insert_terminal_piped_task(&registry, &dir, "true", "", "", false);
            task.lock_state().unwrap().metadata.scope = Some(stamp(scope_ref));
            let (scratch, _) = attach_scratch(&task);
            assert!(registry.cleanup_terminal_task_temp(&task).unwrap());
            assert!(scratch.is_dir());
            kept.push((task, scratch));
        }
        registry.kill_scope(&stamp("ended"));
        let (ended, ended_scratch) = &kept[0];
        wait_for_released_scratch(&registry, ended);
        assert!(!ended_scratch.exists(), "ended scope kept its scratch");
        let (other, other_scratch) = &kept[1];
        assert!(registry.cleanup_terminal_task_temp(other).unwrap());
        assert!(
            other_scratch.is_dir(),
            "another scope's scratch was deleted"
        );
        assert_eq!(registry.try_retained_scratch_health().unwrap().count, 1);
        wait_for_task_temp_cleanup(&registry, other);
    }

    /// A command can finish just before its scope ends and reach scratch
    /// cleanup only afterwards. The scope-end pass then finds nothing listed
    /// to release, so cleanup itself must see that the scope has ended and
    /// delete the scratch now instead of keeping it for the retention time.
    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_scope_ended_before_cleanup_deletes_early() {
        let stamp = |scope_ref: &str| {
            subc_protocol::scope::ScopeStamp::new(
                subc_protocol::Principal::Reserved {
                    module_id: "owner".into(),
                },
                scope_ref,
                1,
                subc_protocol::scope::ScopeKind::Head,
            )
            .with_owner_authorized(true)
        };
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let mut finished = Vec::new();
        for scope_ref in ["ended", "other"] {
            let (_, task) = insert_terminal_piped_task(&registry, &dir, "true", "", "", false);
            task.lock_state().unwrap().metadata.scope = Some(stamp(scope_ref));
            let (scratch, _) = attach_scratch(&task);
            finished.push((task, scratch));
        }
        // The scope ends while both commands have finished but neither has
        // been through scratch cleanup, so no scratch is listed as kept yet.
        assert_eq!(registry.try_retained_scratch_health().unwrap().count, 0);
        registry.kill_scope(&stamp("ended"));

        let (ended, ended_scratch) = &finished[0];
        wait_for_released_scratch(&registry, ended);
        assert!(
            !ended_scratch.exists(),
            "scratch of a scope that ended before cleanup was kept"
        );
        let (other, other_scratch) = &finished[1];
        assert!(registry.cleanup_terminal_task_temp(other).unwrap());
        assert!(
            other_scratch.is_dir(),
            "another scope's scratch was deleted"
        );
        assert_eq!(registry.try_retained_scratch_health().unwrap().count, 1);
        wait_for_task_temp_cleanup(&registry, other);
    }

    #[test]
    #[cfg(unix)]
    fn bash_background_scratch_retention_pruned_record_deletes_kept_scratch() {
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let (_, task) = insert_terminal_piped_task(&registry, &dir, "true", "", "", false);
        task.lock_state().unwrap().metadata.completion_delivered = true;
        let (scratch, _) = attach_scratch(&task);
        assert!(registry.cleanup_terminal_task_temp(&task).unwrap());
        assert!(scratch.is_dir());
        let deadline = Instant::now() + Duration::from_secs(10);
        while task.paths.json.exists() {
            assert!(
                Instant::now() < deadline,
                "record with kept scratch was not pruned"
            );
            registry.cleanup_finished(Duration::ZERO);
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(!scratch.exists(), "pruned record leaked its kept scratch");
        assert_eq!(registry.try_retained_scratch_health().unwrap().count, 0);
    }

    #[test]
    fn bash_background_replay_prefers_exit_marker_written_during_process_probe() {
        for status in [
            BgTaskStatus::Starting,
            BgTaskStatus::Running,
            BgTaskStatus::Killing,
        ] {
            for (code, expected) in [(0, BgTaskStatus::Completed), (7, BgTaskStatus::Failed)] {
                for delivered in [false, true] {
                    let registry = BgTaskRegistry::default();
                    let dir = tempfile::tempdir().unwrap();
                    let paths = task_paths(dir.path(), "session", &random_slug()).unwrap();
                    fs::create_dir_all(&paths.io_dir).unwrap();
                    let mut metadata = PersistedTask::starting(
                        paths.task_id.clone(),
                        "session".into(),
                        format!("exit {code}"),
                        dir.path().into(),
                        None,
                        None,
                        true,
                        false,
                    );
                    metadata.mark_running(u32::MAX, i32::MAX);
                    metadata.status = status.clone();
                    metadata.completion_delivered = delivered;
                    write_task(&paths.json, &metadata).unwrap();
                    let probed = std::cell::Cell::new(false);
                    registry
                        .rehydrate_resolved_task_with_process_probe(
                            metadata,
                            paths.clone(),
                            "session",
                            |_| {
                                assert!(!probed.replace(true));
                                assert_eq!(read_exit_marker(&paths).unwrap(), None);
                                // The wrapper publishes its status after replay's first
                                // marker read, then exits before the liveness probe.
                                fs::write(&paths.exit, code.to_string()).unwrap();
                                false
                            },
                        )
                        .unwrap();
                    assert!(probed.get());
                    let task = registry.task(&paths.task_id).unwrap();
                    let state = task.lock_state().unwrap();
                    assert_eq!(state.metadata.status, expected, "replayed {status:?}");
                    assert_eq!(state.metadata.exit_code, Some(code));
                    assert_eq!(
                        state.metadata.status_reason.as_deref(),
                        (status == BgTaskStatus::Killing)
                            .then_some("recovered from inconsistent killing state on replay")
                    );
                    assert_eq!(state.metadata.exit_marker_unavailable, None);
                    assert_eq!(state.metadata.completion_delivered, delivered);
                    drop(state);
                    let persisted = read_task(&paths.json).unwrap();
                    assert_eq!(persisted.status, expected);
                    assert_eq!(persisted.exit_code, Some(code));
                    assert_eq!(
                        read_exit_marker(&paths).unwrap(),
                        Some(ExitMarker::Code(code as i32))
                    );
                    assert_eq!(
                        registry
                            .drain_completions_for_session(Some("session"))
                            .len(),
                        usize::from(!delivered)
                    );
                }
            }
        }
    }

    #[test]
    fn completion_preview_success_keeps_tail_only() {
        // Exit-aware completion previews: a SUCCESSFUL task's reminder keeps a
        // short tail only — head context is noise when the command worked
        // (regression: the uniform 4 KiB head+tail cap flooded reminders with
        // ~1K tokens of build noise per completed task).
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let output = format!("HEAD-SIGNAL\n{}TAIL-SIGNAL\n", "middle\n".repeat(2_000));
        let (_task_id, task) =
            insert_terminal_piped_task(&registry, &dir, "cat big.log", &output, "", false);

        registry.post_terminal_transition(&task, true).unwrap();
        let completions = registry.drain_completions_for_session(Some("session"));
        assert_eq!(completions.len(), 1);
        let preview = &completions[0].output_preview;
        assert!(preview.contains("TAIL-SIGNAL"), "preview was {preview:?}");
        assert!(!preview.contains("HEAD-SIGNAL"), "preview was {preview:?}");
        assert!(completions[0].output_truncated);
    }

    #[test]
    fn completion_preview_failure_keeps_head_and_tail() {
        // A FAILED task keeps a small head (first error / command banner) plus
        // a larger tail (tracebacks and summaries land at the end).
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let output = format!("HEAD-SIGNAL\n{}TAIL-SIGNAL\n", "middle\n".repeat(2_000));
        let task_id = random_slug();
        let paths = task_paths(dir.path(), "session", &task_id).unwrap();
        fs::create_dir_all(&paths.dir).unwrap();
        fs::write(&paths.stdout, &output).unwrap();
        fs::write(&paths.stderr, "").unwrap();
        let mut metadata = PersistedTask::starting(
            task_id.clone(),
            "session".to_string(),
            "cat big.log".to_string(),
            dir.path().to_path_buf(),
            Some(dir.path().to_path_buf()),
            Some(30_000),
            true,
            false,
        );
        metadata.mark_terminal(BgTaskStatus::Failed, Some(1), None);
        write_task(&paths.json, &metadata).unwrap();
        registry
            .insert_rehydrated_task(metadata, paths, true)
            .expect("insert terminal task");
        let task = registry.task_for_session(&task_id, "session").unwrap();

        // Exercise head/tail sizing rather than restart withholding. The
        // simulated command has a known environment with no secret variables.
        *task.completion_secrets.lock().unwrap() = Some(Default::default());
        registry.post_terminal_transition(&task, true).unwrap();
        let completions = registry.drain_completions_for_session(Some("session"));
        assert_eq!(completions.len(), 1);
        let preview = &completions[0].output_preview;
        assert!(preview.contains("HEAD-SIGNAL"), "preview was {preview:?}");
        assert!(preview.contains("TAIL-SIGNAL"), "preview was {preview:?}");
    }

    #[test]
    #[cfg(unix)]
    fn kill_gated_local_task_frees_slot_without_running_command() {
        struct Release(std::sync::mpsc::Sender<()>);
        impl Drop for Release {
            fn drop(&mut self) {
                let _ = self.0.send(());
            }
        }
        let dir = tempfile::tempdir().unwrap();
        let marker = dir.path().join("must-not-run");
        let registry = BgTaskRegistry::default();
        let (arrived_tx, arrived_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        *registry.inner.before_bootstrap_release.lock().unwrap() = Some((arrived_tx, release_rx));
        let release = Release(release_tx);
        let spawning = registry.clone();
        let project = dir.path().to_path_buf();
        let command = format!("printf ran > '{}'", marker.display());
        let worker = std::thread::spawn(move || {
            spawning.spawn(
                SpawnPlan::Unsandboxed,
                &command,
                "session".into(),
                project.clone(),
                HashMap::new(),
                super::super::HardKill::After(Duration::from_secs(30)),
                project.clone(),
                1,
                false,
                false,
                Some(project),
            )
        });
        let id = arrived_rx
            .recv_timeout(Duration::from_secs(3))
            .expect("child reached bootstrap checkpoint");
        assert!(!marker.exists());
        let refusal = registry
            .check_background_slot(super::super::TaskSlot::Background { max: 1 }, "session")
            .expect_err("gated task must reserve its background slot before running");
        assert!(refusal.contains(&id), "{refusal}");
        let killed = registry
            .kill(&id, "session")
            .expect("gated task must already be killable");
        assert_eq!(killed.info.status, BgTaskStatus::Killed);
        registry
            .check_background_slot(super::super::TaskSlot::Background { max: 1 }, "session")
            .expect("kill releases background slot synchronously");
        assert!(
            registry.inner.background_admission.try_lock().is_ok(),
            "killed spawn must not retain admission lock"
        );
        assert!(!marker.exists(), "killed gated command executed");
        let replacement = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                "sleep 30 # replacement-slot-holder",
                "session".into(),
                dir.path().into(),
                HashMap::new(),
                super::super::HardKill::After(Duration::from_secs(30)),
                dir.path().into(),
                1,
                false,
                false,
                Some(dir.path().into()),
            )
            .expect("replacement starts before killed spawner resumes");
        registry.kill(&replacement, "session").unwrap();
        drop(release);
        assert_eq!(worker.join().unwrap().unwrap(), id);
        assert!(
            !marker.exists(),
            "late gate release executed killed command"
        );
    }

    #[test]
    #[cfg(unix)]
    fn poisoned_watchdog_registration_closes_the_identity_gate() {
        use std::collections::HashMap;
        use std::sync::Arc;
        use std::time::{Duration, Instant};

        let root = tempfile::tempdir().unwrap();
        let marker = root.path().join("must-not-run");
        let registry = super::BgTaskRegistry::default();
        let inner = Arc::clone(&registry.inner);
        let poison = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _watchdog_tasks = inner.watchdog_tasks.lock().unwrap();
            panic!("poison the watchdog task map before spawn registration");
        }));
        assert!(poison.is_err());

        let command = format!("printf ran > '{}'", marker.display());
        let error = registry
            .spawn(
                super::SpawnPlan::Unsandboxed,
                &command,
                "session".into(),
                root.path().to_path_buf(),
                HashMap::new(),
                super::super::HardKill::After(Duration::from_secs(30)),
                root.path().to_path_buf(),
                1,
                false,
                false,
                Some(root.path().to_path_buf()),
            )
            .unwrap_err();
        assert!(
            error.contains("background watchdog lock poisoned"),
            "{error}"
        );

        let task = registry
            .task_arcs()
            .into_iter()
            .next()
            .expect("task was inserted before watchdog registration failed");
        let pgid = {
            let state = task.lock_state().unwrap();
            let super::TaskRuntime::Piped(Some(child)) = &state.runtime else {
                panic!("failed registration must retain its child handle");
            };
            child.id() as i32
        };
        struct KillGroupOnDrop(i32);
        impl Drop for KillGroupOnDrop {
            fn drop(&mut self) {
                unsafe {
                    libc::kill(-self.0, libc::SIGKILL);
                }
            }
        }
        let _kill_group_on_drop = KillGroupOnDrop(pgid);
        let deadline = Instant::now() + Duration::from_secs(5);
        let status = loop {
            let mut state = task.lock_state().unwrap();
            let super::TaskRuntime::Piped(Some(child)) = &mut state.runtime else {
                panic!("failed registration must retain its child handle");
            };
            if let Some(status) = child.try_wait().unwrap() {
                break status;
            }
            drop(state);
            assert!(
                Instant::now() < deadline,
                "identity-gated child did not exit"
            );
            std::thread::sleep(Duration::from_millis(10));
        };
        assert_eq!(status.code(), Some(125));
        assert!(
            !marker.exists(),
            "the command ran without an identity release"
        );
    }

    #[test]
    fn recovered_terminal_reply_matches_live_status_text() {
        use crate::commands::bash_orchestrate::{decide_bash_step, BashStep};
        for (status, exit, reason, expected) in [
            (BgTaskStatus::Failed, None, Some("spawn aborted"), "failed"),
            (BgTaskStatus::Failed, Some(17), None, "[exit code: 17]"),
            (BgTaskStatus::Killed, None, None, "killed"),
            (
                BgTaskStatus::Killed,
                None,
                Some("cancelled by caller"),
                "killed",
            ),
            (
                BgTaskStatus::TimedOut,
                None,
                Some("timeout elapsed"),
                "[command timed out]",
            ),
            (BgTaskStatus::Failed, Some(0x8000_0000), None, "2147483648"),
        ] {
            let dir = tempfile::tempdir().unwrap();
            let task_id = random_slug();
            let paths = task_paths(dir.path(), "session", &task_id).unwrap();
            let mut metadata = PersistedTask::starting(
                task_id,
                "session".into(),
                "unused".into(),
                dir.path().to_path_buf(),
                Some(dir.path().to_path_buf()),
                None,
                false,
                false,
            );
            metadata.mark_terminal(status.clone(), exit, reason.map(str::to_string));
            let row = metadata.to_bash_task_row("runner", &paths).unwrap();
            let snapshot = terminal_db_row_snapshot(row, metadata);
            let now = Instant::now();
            let BashStep::Done(live) =
                decide_bash_step(snapshot.clone(), now, true, false, now, "terminal")
            else {
                panic!("terminal record must have a live foreground result");
            };
            let context = crate::subc_format::FormatContext::from_tool_call(
                "bash",
                &serde_json::json!({}),
                dir.path(),
            );
            let live_text =
                crate::subc_format::format_response_with_context("bash", &live, &context);
            let key = crate::db::call_ledger::Key {
                carrier: "reserved:carrier".into(),
                call_key: "terminal".into(),
            };
            let (frame, _) = crate::subc::recovered_bash_frame(snapshot, &key, dir.path())
                .expect("terminal recovered frame");
            let body: serde_json::Value = serde_json::from_slice(&frame.body).unwrap();
            assert_eq!(body["content"][0]["text"], live_text);
            assert!(
                live.success,
                "a failed command is still a successful tool call"
            );
            assert_eq!(body["isError"], false);
            assert!(
                live_text.contains(expected),
                "terminal {status:?}/{exit:?}/{reason:?} lost its status: {body}"
            );
            if let Some(reason) = reason {
                assert!(live_text.contains(reason), "{live_text}");
            }
        }
    }

