    #[test]
    fn register_watch_on_terminal_task_scans_existing_output() {
        let frames = Arc::new(Mutex::new(Vec::new()));
        let captured = Arc::clone(&frames);
        let sender: crate::context::ProgressSender = Arc::new(Box::new(move |frame| {
            captured.lock().unwrap().push(frame);
        })
            as Box<dyn Fn(PushFrame) + Send + Sync>);
        let registry = BgTaskRegistry::new(Arc::new(Mutex::new(Some(sender))));
        let dir = tempfile::tempdir().unwrap();
        let task_id = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                LONG_RUNNING_COMMAND,
                "session".to_string(),
                dir.path().to_path_buf(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                dir.path().to_path_buf(),
                10,
                true,
                false,
                Some(dir.path().to_path_buf()),
            )
            .unwrap();
        registry
            .inner
            .shutdown
            .store(true, std::sync::atomic::Ordering::SeqCst);
        let task = registry.task_for_session(&task_id, "session").unwrap();
        std::fs::write(&task.paths.stdout, "READY\n").unwrap();
        registry
            .kill_with_status(&task_id, "session", BgTaskStatus::Killed)
            .unwrap();
        frames.lock().unwrap().clear();
        registry.inner.completions.lock().unwrap().clear();

        registry
            .register_watch(
                task_id.clone(),
                WatchPattern::Substring("READY".into()),
                true,
            )
            .unwrap();

        let frames = frames.lock().unwrap();
        let frame = frames
            .iter()
            .find_map(|frame| match frame {
                PushFrame::BashPatternMatch(frame) => Some(frame),
                _ => None,
            })
            .expect("terminal watch registration should emit pattern frame");
        assert_eq!(frame.reason, "pattern_match");
        assert_eq!(frame.task_id, task_id);
        assert_eq!(frame.session_id, "session");
        assert_eq!(frame.match_text, "READY");
        assert_eq!(frame.match_offset, 0);
        assert_eq!(registry.active_watch_count(&frame.task_id), 0);
        let metadata = read_task(&task.paths.json).unwrap();
        assert!(
            !metadata.completion_delivered,
            "terminal pattern notification remains unacked until explicit ack"
        );
        drop(frames);
        assert_eq!(
            registry.ack_completions_for_session(Some("session"), std::slice::from_ref(&task_id),),
            vec![task_id]
        );
        assert!(read_task(&task.paths.json).unwrap().completion_delivered);
    }

    #[test]
    fn cleanup_finished_removes_terminal_tasks_older_than_threshold() {
        let registry = BgTaskRegistry::default();
        let dir = tempfile::tempdir().unwrap();
        let task_id = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                QUICK_SUCCESS_COMMAND,
                "session".to_string(),
                dir.path().to_path_buf(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                dir.path().to_path_buf(),
                10,
                true,
                false,
                Some(dir.path().to_path_buf()),
            )
            .unwrap();
        registry
            .kill_with_status(&task_id, "session", BgTaskStatus::Killed)
            .unwrap();
        let completions = registry.drain_completions_for_session(Some("session"));
        assert_eq!(completions.len(), 1);
        assert_eq!(
            registry.ack_completions_for_session(Some("session"), std::slice::from_ref(&task_id)),
            vec![task_id.clone()]
        );

        let task = registry.task_for_session(&task_id, "session").unwrap();
        let delete_attempted = AtomicBool::new(false);
        let delete_error = Mutex::new(None);
        registry.cleanup_finished_at_with(Duration::ZERO, Instant::now(), |candidate| {
            delete_attempted.store(true, Ordering::SeqCst);
            let state = task.lock_state().unwrap();
            assert!(
                state.io_handles.is_none(),
                "cleanup must close task IO handles before deleting its bundle"
            );
            assert!(
                matches!(
                    &state.runtime,
                    TaskRuntime::Piped(None) | TaskRuntime::Pty(None)
                ),
                "cleanup must drop the child or PTY runtime before deleting its bundle"
            );
            assert!(
                state.child_exit_observed,
                "cleanup must observe the direct child exit before deleting its output files"
            );
            assert!(
                task.terminal_reader_done.load(Ordering::SeqCst),
                "cleanup must wait for the PTY reader's output-file handle"
            );
            drop(state);
            match delete_task_bundle(&candidate.paths) {
                Ok(()) => Ok(()),
                Err(error) => {
                    *delete_error.lock().unwrap() = Some(error.to_string());
                    Err(error)
                }
            }
        });

        let delete_result = delete_error.lock().unwrap().clone().unwrap_or_else(|| {
            if delete_attempted.load(Ordering::SeqCst) {
                "delete_bundle returned success".to_string()
            } else {
                "delete_bundle was skipped because task handles remained open".to_string()
            }
        });
        assert!(
            registry.inner.tasks.lock().unwrap().is_empty(),
            "finished task was not removed after one sweep; delete result: {delete_result}"
        );
        assert!(
            !task.paths.json.exists(),
            "finished task metadata remains after one sweep; delete result: {delete_result}"
        );
    }

