    #[test]
    fn standalone_same_project_multi_session_replay_preserves_earlier_session_delivery() {
        let storage = tempfile::tempdir().unwrap();
        let project = tempfile::tempdir().unwrap();
        let (registry, _db, frames) = registry_with_db_and_frames(storage.path());

        // Session A replays for the project, spawns a watched task, and spawns a completion task.
        registry
            .replay_session_for_project(storage.path(), "session-a", project.path())
            .unwrap();

        let task_watch = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                LONG_RUNNING_COMMAND,
                "session-a".to_string(),
                project.path().to_path_buf(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                storage.path().to_path_buf(),
                10,
                true,
                false,
                Some(project.path().to_path_buf()),
            )
            .unwrap();
        registry
            .register_watch(
                task_watch.clone(),
                WatchPattern::Substring("READY".into()),
                true,
            )
            .unwrap();

        let task_comp = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                LONG_RUNNING_COMMAND,
                "session-a".to_string(),
                project.path().to_path_buf(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                storage.path().to_path_buf(),
                10,
                true,
                false,
                Some(project.path().to_path_buf()),
            )
            .unwrap();

        // Session B replays for the same project on the shared standalone bridge.
        registry
            .replay_session_for_project(storage.path(), "session-b", project.path())
            .unwrap();

        // Session A's watched task produces matching output.
        let watch_handle = registry.task_for_session(&task_watch, "session-a").unwrap();
        std::fs::OpenOptions::new()
            .append(true)
            .open(&watch_handle.paths.stdout)
            .unwrap()
            .write_all(b"READY\n")
            .unwrap();
        registry.scan_task_watch_output(&watch_handle);

        // Session A's background completion task completes.
        let comp_handle = registry.task_for_session(&task_comp, "session-a").unwrap();
        fs::write(&comp_handle.paths.exit, "0\n").unwrap();
        comp_handle.mark_terminal_now();
        comp_handle.lock_state().unwrap().metadata.mark_terminal(
            BgTaskStatus::Completed,
            Some(0),
            None,
        );
        registry
            .post_terminal_transition(&comp_handle, true)
            .unwrap();

        // The completion task was marked terminal while its child is still
        // running, so the descendant sampler finds a survivor and the frame is
        // emitted after its grace period rather than inline.
        let deadline = Instant::now() + Duration::from_secs(5);
        loop {
            let emitted = frames.lock().unwrap().iter().any(
                |frame| matches!(frame, PushFrame::BashCompleted(f) if f.task_id == task_comp),
            );
            if emitted || Instant::now() >= deadline {
                break;
            }
            std::thread::sleep(Duration::from_millis(20));
        }

        let captured = frames.lock().unwrap();
        let pattern_matches = captured
            .iter()
            .filter_map(|frame| match frame {
                PushFrame::BashPatternMatch(frame) => Some(frame),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            pattern_matches.iter().any(|f| f.task_id == task_watch
                && f.session_id == "session-a"
                && f.match_text == "READY"),
            "session A pattern match must be emitted after session B replay: {pattern_matches:?}"
        );

        let completions = captured
            .iter()
            .filter_map(|frame| match frame {
                PushFrame::BashCompleted(frame) => Some(frame),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert!(
            completions
                .iter()
                .any(|f| f.task_id == task_comp && f.session_id == "session-a"),
            "session A completion must be emitted after session B replay: {completions:?}"
        );
    }

    #[cfg(unix)]
    #[test]
    fn gc_refuses_to_delete_or_quarantine_a_recorded_live_process() {
        let dir = tempfile::tempdir().unwrap();
        let storage = dir.path();
        let (registry, db, _frames) = registry_with_db_and_frames(storage);
        let task_id = "bash-0000000000000198";
        let paths = task_paths(storage, "session", task_id).unwrap();
        let mut running = PersistedTask::starting(
            task_id.to_string(),
            "session".to_string(),
            "live-process-canary".to_string(),
            storage.to_path_buf(),
            Some(storage.to_path_buf()),
            None,
            true,
            false,
        );
        // Own-PID is safe here because GC only CHECKS liveness (it refuses
        // to delete live bundles, never signals them). Kill-path tests must
        // spawn a disposable child instead - see bash_kill.rs.
        running.mark_running(std::process::id(), std::process::id() as i32);
        write_task(&paths.json, &running).unwrap();
        fs::write(&paths.stdout, b"").unwrap();
        fs::write(&paths.stderr, b"").unwrap();
        {
            let conn = db.lock().unwrap();
            crate::db::bash_tasks::upsert_bash_task(
                &conn,
                &running.to_bash_task_row("opencode", &paths).unwrap(),
            )
            .unwrap();
        }
        let running_json = fs::read(&paths.json).unwrap();
        let mut terminal: PersistedTask = serde_json::from_slice(&running_json).unwrap();
        terminal.mark_terminal(BgTaskStatus::Completed, Some(0), None);
        terminal.completion_delivered = true;
        write_task_at(
            &resolve_task_layout(&paths.session_dir, task_id).unwrap(),
            &terminal,
        )
        .unwrap();
        let old = SystemTime::now()
            .checked_sub(Duration::from_secs(25 * 60 * 60))
            .unwrap();
        filetime::set_file_mtime(&paths.json, filetime::FileTime::from_system_time(old)).unwrap();

        assert_eq!(registry.maybe_gc_persisted(storage).unwrap(), 0);
        assert!(paths.io_dir.exists(), "GC deleted a live task bundle");

        fs::write(&paths.json, b"{corrupt").unwrap();
        filetime::set_file_mtime(&paths.json, filetime::FileTime::from_system_time(old)).unwrap();
        assert_eq!(registry.maybe_gc_persisted(storage).unwrap(), 0);
        assert!(
            paths.io_dir.exists(),
            "GC quarantined a live task with unreadable metadata"
        );

        fs::write(&paths.json, running_json).unwrap();
    }

    /// An ack can reach a registry that does not hold the task (another
    /// project root's actor), which marks the aft.db row delivered directly.
    /// A snapshot can be captured after the ack's fence drains the pending
    /// row but before its SQL update. That snapshot must not undo the ack
    /// when it flushes later, or restart replay will deliver a duplicate.
    #[cfg(unix)]
    #[test]
    fn queued_row_snapshot_cannot_undo_a_foreign_registry_ack() {
        let storage = tempfile::tempdir().unwrap();
        let (owner, db, _frames) = registry_with_db_and_frames(storage.path());
        let (task_id, task) =
            insert_terminal_piped_task(&owner, &storage, "echo done", "done\n", "", false);
        owner.write_current_task_row(&task);
        let row = |db: &Mutex<TrackedConnection>| {
            crate::db::bash_tasks::get_bash_task(
                &db.lock().unwrap(),
                "opencode",
                "session",
                &task_id,
            )
            .unwrap()
            .expect("bash_tasks row")
        };
        assert_eq!(row(&db).status, "completed");
        assert!(!row(&db).completion_delivered);

        // The foreign registry shares aft.db but does not hold the task.
        let foreign = BgTaskRegistry::new(Arc::new(Mutex::new(None)));
        foreign.set_harness(Harness::Opencode);
        foreign.set_db_pool(Arc::clone(&db));

        let (parked_tx, parked_rx) = std::sync::mpsc::channel();
        let (release_tx, release_rx) = std::sync::mpsc::channel();
        *task.db_write_order.before_fenced_change.lock().unwrap() = Some(Box::new(move || {
            parked_tx.send(()).unwrap();
            release_rx.recv_timeout(CHILD_EXIT_LIVENESS_BOUND).unwrap();
        }));
        let ack = {
            let foreign = foreign.clone();
            let task_id = task_id.clone();
            std::thread::spawn(move || {
                foreign.ack_completions_for_session(Some("session"), &[task_id])
            })
        };
        parked_rx.recv_timeout(CHILD_EXIT_LIVENESS_BOUND).unwrap();
        // The fence holds the flush lock, not the task or JSON-write locks.
        // A live owner can still persist and queue undelivered metadata here.
        let mut queued = DeferredDbWrites::new(&owner, &task);
        {
            let state = task.lock_state().unwrap();
            assert!(!state.metadata.completion_delivered);
            owner
                .persist_task_locked(&task, &state.metadata, &mut queued)
                .unwrap();
        }
        release_tx.send(()).unwrap();
        assert_eq!(ack.join().unwrap(), vec![task_id.clone()]);
        assert!(row(&db).completion_delivered, "ack was not durable");
        drop(queued);

        assert!(
            row(&db).completion_delivered,
            "a snapshot captured before the ack flipped the row back to undelivered"
        );
        assert!(
            PersistedTask::from(row(&db)).completion_delivered,
            "row decoding lost the durable ack"
        );
    }

    #[cfg(unix)]
    #[test]
    fn disk_replay_cannot_undo_a_foreign_registry_ack() {
        for project_scoped in [false, true] {
            for prefer_disk in [false, true] {
                let storage = tempfile::tempdir().unwrap();
                let (owner, db, _frames) = registry_with_db_and_frames(storage.path());
                let (task_id, task) =
                    insert_terminal_piped_task(&owner, &storage, "echo done", "done\n", "", false);
                {
                    let mut queued = DeferredDbWrites::new(&owner, &task);
                    let mut state = task.lock_state().unwrap();
                    state.metadata.local_fallback_started = prefer_disk;
                    owner
                        .persist_task_locked(&task, &state.metadata, &mut queued)
                        .unwrap();
                }
                let foreign = BgTaskRegistry::new(Arc::new(Mutex::new(None)));
                foreign.set_harness(Harness::Opencode);
                foreign.set_db_pool(Arc::clone(&db));
                assert_eq!(
                    foreign.ack_completions_for_session(Some("session"), &[task_id.clone()]),
                    vec![task_id.clone()]
                );
                assert!(!read_task(&task.paths.json).unwrap().completion_delivered);

                let replay = BgTaskRegistry::new(Arc::new(Mutex::new(None)));
                replay.set_harness(Harness::Opencode);
                replay.set_db_pool(Arc::clone(&db));
                // Keep this replay focused on recovery rather than the detached GC.
                replay
                    .inner
                    .persisted_gc_started
                    .store(true, Ordering::SeqCst);
                if project_scoped {
                    replay
                        .replay_session_for_project(storage.path(), "session", storage.path())
                        .unwrap();
                } else {
                    replay.replay_session(storage.path(), "session").unwrap();
                }
                assert!(
                    replay.drain_completions().is_empty(),
                    "durably acked task was replayed: project_scoped={project_scoped}, prefer_disk={prefer_disk}"
                );
                assert!(
                    replay
                        .task_for_session(&task_id, "session")
                        .unwrap()
                        .lock_state()
                        .unwrap()
                        .metadata
                        .completion_delivered,
                    "rehydration lost the durable ack"
                );
            }
        }
    }

    #[test]
    fn replay_session_batch_restores_all_disk_tasks_when_aft_db_is_unreadable() {
        let storage = tempfile::tempdir().unwrap();
        let (owner, db, _frames) = registry_with_db_and_frames(storage.path());
        let task_ids = (0..3)
            .map(|index| {
                insert_terminal_piped_task(
                    &owner,
                    &storage,
                    &format!("echo task {index}"),
                    &format!("task {index}\n"),
                    "",
                    false,
                )
                .0
            })
            .collect::<Vec<_>>();

        // Make both the initial task-list query and the acknowledgement reads fail.
        db.lock()
            .unwrap()
            .execute_batch("DROP TABLE bash_tasks")
            .unwrap();

        let replay = BgTaskRegistry::new(Arc::new(Mutex::new(None)));
        replay.set_harness(Harness::Opencode);
        replay.set_db_pool(db);
        replay
            .inner
            .persisted_gc_started
            .store(true, Ordering::SeqCst);

        let (_, logs) = crate::logging::capture_log_lines(|| {
            replay
                .replay_session(storage.path(), "session")
                .expect("unreadable database must not stop disk replay");
        });

        let fallback_warnings = logs
            .iter()
            .filter(|line| {
                line.contains("falling back to disk without durable completion acknowledgements")
            })
            .collect::<Vec<_>>();
        assert_eq!(fallback_warnings.len(), 1, "{logs:?}");
        assert!(fallback_warnings[0].contains("no such table: bash_tasks"));
        assert!(
            logs.iter()
                .all(|line| !line.contains("completion acknowledgement lookup failed")),
            "replay retried the unreadable database for each task: {logs:?}"
        );

        for task_id in task_ids {
            assert!(
                replay.task_for_session(&task_id, "session").is_some(),
                "disk task was not restored: {task_id}"
            );
            assert!(
                replay
                    .pending_completions_for_session("session")
                    .iter()
                    .any(|completion| completion.task_id == task_id),
                "pending completion was not queued: {task_id}"
            );
        }
    }

    /// A daemon restart replays every project root at once, and each root's
    /// registry asks for a persisted-task GC of the one shared storage root.
    /// One sweep must serve them all, and it must ask aft.db about recorded
    /// processes once per session rather than once per task: every such
    /// query takes the process-wide aft.db mutex.
    #[cfg(unix)]
    #[test]
    fn restart_replay_of_many_registries_runs_one_batched_persisted_gc() {
        const REGISTRIES: usize = 8;
        const SESSIONS: usize = 6;
        const TASKS_PER_SESSION: usize = 5;

        let dir = tempfile::tempdir().unwrap();
        let storage = dir.path();
        let db = Arc::new(Mutex::new(
            crate::db::open(&storage.join("aft.db")).expect("open test DB"),
        ));
        let old = SystemTime::now()
            .checked_sub(Duration::from_secs(25 * 60 * 60))
            .unwrap();
        let mut fixtures = Vec::new();
        for session in 0..SESSIONS {
            let session_id = format!("session-{session}");
            for task in 0..TASKS_PER_SESSION {
                let task_id = format!("bash-{:016x}", session * 100 + task);
                let paths = task_paths(storage, &session_id, &task_id).unwrap();
                let starting = PersistedTask::starting(
                    task_id.clone(),
                    session_id.clone(),
                    "gc-herd-canary".to_string(),
                    storage.to_path_buf(),
                    Some(storage.to_path_buf()),
                    None,
                    true,
                    false,
                );
                // Delivered and old enough to delete, with no process in the
                // JSON; the aft.db row records a live one (this process, which
                // the GC only probes), so every task reaches the database
                // check and survives every sweep.
                let mut terminal = starting.clone();
                terminal.mark_terminal(BgTaskStatus::Completed, Some(0), None);
                terminal.completion_delivered = true;
                write_task(&paths.json, &terminal).unwrap();
                fs::write(&paths.stdout, b"").unwrap();
                fs::write(&paths.stderr, b"").unwrap();
                filetime::set_file_mtime(&paths.json, filetime::FileTime::from_system_time(old))
                    .unwrap();
                let mut running = starting;
                running.mark_running(std::process::id(), std::process::id() as i32);
                crate::db::bash_tasks::upsert_bash_task(
                    &db.lock().unwrap(),
                    &running.to_bash_task_row("opencode", &paths).unwrap(),
                )
                .unwrap();
                fixtures.push(paths);
            }
        }

        let registries: Vec<BgTaskRegistry> = (0..REGISTRIES)
            .map(|_| {
                let registry = BgTaskRegistry::new(Arc::new(Mutex::new(None)));
                registry.set_harness(Harness::Opencode);
                registry.set_db_pool(Arc::clone(&db));
                registry
            })
            .collect();
        let barrier = Arc::new(std::sync::Barrier::new(REGISTRIES));
        let replays: Vec<_> = registries
            .iter()
            .enumerate()
            .map(|(index, registry)| {
                let registry = registry.clone();
                let barrier = Arc::clone(&barrier);
                let storage = storage.to_path_buf();
                std::thread::spawn(move || {
                    barrier.wait();
                    registry
                        .replay_session(&storage, &format!("replay-{index}"))
                        .unwrap();
                })
            })
            .collect();
        for replay in replays {
            replay.join().unwrap();
        }
        let deadline = Instant::now() + Duration::from_secs(30);
        while registries
            .iter()
            .any(|registry| registry.persisted_gc_thread().is_none())
        {
            assert!(
                Instant::now() < deadline,
                "a replay's persisted GC never finished"
            );
            std::thread::sleep(Duration::from_millis(10));
        }

        let sweeps: u64 = registries
            .iter()
            .map(|registry| registry.inner.persisted_gc_runs.load(Ordering::SeqCst))
            .sum();
        let queries: u64 = registries
            .iter()
            .map(|registry| registry.inner.gc_db_liveness_queries.load(Ordering::SeqCst))
            .sum();
        eprintln!(
            "restart replay of {REGISTRIES} registries over {SESSIONS} sessions x {TASKS_PER_SESSION} tasks: {sweeps} GC sweeps, {queries} aft.db liveness queries"
        );
        for registry in &registries {
            assert_eq!(
                registry.persisted_gc_thread().as_deref(),
                Some("aft-bash-task-gc")
            );
            registry.shutdown();
        }
        assert!(
            fixtures.iter().all(|paths| paths.json.exists()),
            "GC deleted a task whose aft.db row records a live process"
        );
        assert_eq!(sweeps, 1, "one sweep must serve every registry");
        assert_eq!(
            queries, SESSIONS as u64,
            "the sweep must ask aft.db once per session"
        );
    }

    #[test]
    fn pattern_watch_survives_registry_teardown_and_rehydrate() {
        let dir = tempfile::tempdir().unwrap();
        let storage = dir.path();
        let (registry, _db, frames) = registry_with_db_and_frames(storage);
        let _reap = KillTasksOnDrop(registry.clone());
        let task_id = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                LONG_RUNNING_COMMAND,
                "session".to_string(),
                storage.to_path_buf(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                storage.to_path_buf(),
                10,
                true,
                false,
                Some(storage.to_path_buf()),
            )
            .unwrap();
        registry
            .register_watch(
                task_id.clone(),
                WatchPattern::Substring("READY".into()),
                true,
            )
            .unwrap();
        let task = registry.task_for_session(&task_id, "session").unwrap();
        // Simulate bridge death: drop in-memory watches only. Durable rows remain.
        registry.clear_task_watch_state(&task_id);
        assert_eq!(registry.active_watch_count(&task_id), 0);

        std::fs::OpenOptions::new()
            .append(true)
            .open(&task.paths.stdout)
            .unwrap()
            .write_all(b"READY\n")
            .unwrap();
        frames.lock().unwrap().clear();

        let (replayed, _db2, replay_frames) = registry_with_db_and_frames(storage);
        let _reap_replayed = KillTasksOnDrop(replayed.clone());
        // Keep the original process's task row out of the way; replay loads from DB/disk.
        registry
            .inner
            .shutdown
            .store(true, std::sync::atomic::Ordering::SeqCst);
        replayed
            .replay_session_inner(storage, "session", None)
            .unwrap();

        let matches = pattern_match_frames(&replay_frames);
        assert!(
            matches.iter().any(|frame| {
                frame.task_id == task_id
                    && frame.reason == "pattern_match"
                    && frame.match_text == "READY"
                    && frame.context == "READY\n"
            }),
            "rehydrate should deliver gap match: {matches:?}"
        );
    }

    #[test]
    #[cfg(unix)]
    fn a02_running_watch_catches_up_before_child_exit() {
        use crate::bash_background::persistence::work_counts;
        let dir = tempfile::tempdir().unwrap();
        let storage = dir.path();
        let (registry, _db, frames) = registry_with_db_and_frames(storage);
        registry.inner.shutdown.store(true, Ordering::SeqCst);
        let go = storage.join("go");
        // The line break keeps LATE's line within the watch preview's mask cap;
        // LATE still arrives in the fourth 64 KiB scan chunk.
        let command = format!("while [ ! -e '{}' ]; do sleep 0.01; done; head -c 196608 /dev/zero; printf '\\nLATE'; sleep 30", go.display());
        let id = registry
            .spawn(
                SpawnPlan::Unsandboxed,
                &command,
                "session".into(),
                storage.into(),
                HashMap::new(),
                crate::bash_background::HardKill::After(Duration::from_secs(30)),
                storage.into(),
                10,
                true,
                false,
                Some(storage.into()),
            )
            .unwrap();
        registry
            .register_watch(id.clone(), WatchPattern::Substring("LATE".into()), true)
            .unwrap();
        let task = registry.task_for_session(&id, "session").unwrap();
        fs::write(&go, "").unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        while fs::metadata(&task.paths.stdout).unwrap().len() < 196612 {
            assert!(
                Instant::now() < deadline,
                "producer never emitted the burst"
            );
            std::thread::sleep(Duration::from_millis(1));
        }
        work_counts::reset();
        registry.scan_task_watch_output(&task);
        let work = work_counts::get();
        let still_running = task.state.lock().unwrap().metadata.status == BgTaskStatus::Running;
        let hits = pattern_match_frames(&frames);
        registry.kill(&id, "session").unwrap();
        assert!(still_running, "the match must not depend on terminal drain");
        assert!(
            hits.iter()
                .any(|hit| hit.task_id == id && hit.match_text == "LATE"),
            "late-stream match was not caught in one fair running scan; read {} bytes",
            work.artifact_bytes
        );
        // Matching stays chunked. Presentation reads only a bounded neighborhood
        // of the hit instead of rereading the entire capture for masking.
        assert!(work.artifact_bytes > 196612);
        assert!(work.artifact_bytes <= 196612 + completion_preview::WATCH_PREVIEW_SOURCE_BYTES);
        assert_eq!(
            work.artifact_opens, 2,
            "fresh validation is shared by all chunks in this pass"
        );
    }

    #[test]
    fn a02_running_watch_preserves_stream_chunk_order() {
        let dir = tempfile::tempdir().unwrap();
        let (registry, _db, frames) = registry_with_db_and_frames(dir.path());
        let task = lifecycle_running_fixture(&registry, &dir);
        registry
            .register_watch(
                task.task_id.clone(),
                WatchPattern::Substring("WINNER".into()),
                true,
            )
            .unwrap();
        fs::write(&task.paths.stdout, "x".repeat(64 * 1024) + "WINNER stdout").unwrap();
        fs::write(&task.paths.stderr, "WINNER stderr").unwrap();
        registry.scan_task_watch_output(&task);
        let hits = pattern_match_frames(&frames);
        assert_eq!(hits.len(), 1);
        assert_eq!(
            hits[0].match_offset, 0,
            "stderr's first chunk must win before stdout's second chunk for a once watch"
        );
        assert!(hits[0].context.contains("stderr"));
    }

    #[test]
    fn noisy_watch_scan_is_bounded_and_other_task_matches() {
        let dir = tempfile::tempdir().unwrap();
        let storage = dir.path();
        let (registry, _db, frames) = registry_with_db_and_frames(storage);
        let _reap = KillTasksOnDrop(registry.clone());
        registry.inner.shutdown.store(true, Ordering::SeqCst);
        let spawn = || {
            registry
                .spawn(
                    SpawnPlan::Unsandboxed,
                    LONG_RUNNING_COMMAND,
                    "session".to_string(),
                    storage.to_path_buf(),
                    HashMap::new(),
                    crate::bash_background::HardKill::After(Duration::from_secs(30)),
                    storage.to_path_buf(),
                    10,
                    true,
                    false,
                    Some(storage.to_path_buf()),
                )
                .unwrap()
        };
        let noisy = spawn();
        let other = spawn();
        registry
            .register_watch(
                noisy.clone(),
                WatchPattern::Substring("CROSS-CHUNK".into()),
                true,
            )
            .unwrap();
        registry
            .register_watch(other.clone(), WatchPattern::Substring("READY".into()), true)
            .unwrap();
        let noisy_task = registry.task_for_session(&noisy, "session").unwrap();
        let other_task = registry.task_for_session(&other, "session").unwrap();
        let mut burst = vec![b'x'; 1024 * 1024 - 5];
        // Line breaks keep the match's line within the watch preview's mask
        // cap; CROSS-CHUNK still straddles the 1 MiB tick boundary.
        let line_break = burst.len() - 200;
        burst[line_break] = b'\n';
        burst.extend_from_slice(b"CROSS-CHUNK\n");
        burst.extend(std::iter::repeat_n(b'x', 1024 * 1024 - 1));
        std::fs::OpenOptions::new()
            .append(true)
            .open(&noisy_task.paths.stdout)
            .unwrap()
            .write_all(&burst)
            .unwrap();
        std::fs::OpenOptions::new()
            .append(true)
            .open(&other_task.paths.stdout)
            .unwrap()
            .write_all(b"READY")
            .unwrap();
        // On Windows the long-running command prints to the same stdout file,
        // so the watch can start past offset zero. Measure the tick from
        // wherever the cursor stood before it.
        let before = registry.watch_stream_cursors(&noisy).0;
        registry.scan_task_watch_output(&noisy_task);
        let first = registry.watch_stream_cursors(&noisy).0;
        assert_eq!(
            first - before,
            1024 * 1024,
            "one running tick must not consume the whole burst"
        );
        registry.scan_task_watch_output(&other_task);
        registry.scan_task_watch_output(&noisy_task);
        let hits = pattern_match_frames(&frames);
        assert!(hits
            .iter()
            .any(|hit| hit.task_id == other && hit.match_text == "READY"));
        assert!(hits
            .iter()
            .any(|hit| hit.task_id == noisy && hit.match_text == "CROSS-CHUNK"));
    }

